pragma solidity ^0.8.0;

contract SelfLiquidationBug {
    struct CreditPosition {
        uint256 collateralAmount; // Collateral in ETH
        uint256 debtAmount;       // Debt in USDC
        address lender;           // Address of the lender
    }

    mapping(uint256 => CreditPosition) public creditPositions;
    uint256 public creditPositionCounter = 1;

    // Simplified collateral ratio calculation (assuming 1 ETH = 1000 USDC)
    function collateralRatio(uint256 creditPositionId) public view returns (uint256) {
        CreditPosition memory position = creditPositions[creditPositionId];
        return (position.collateralAmount * 1000) / position.debtAmount;
    }

    // Simplified self-liquidation function (vulnerable to the bug)
    function selfLiquidate(uint256 creditPositionId) public {
        CreditPosition storage position = creditPositions[creditPositionId];

        // Check if the position belongs to the caller (lender)
        require(msg.sender == position.lender, "Only the lender can self-liquidate");

        // Vulnerable check: Only checks if the collateral ratio is below 100%
        // Does not consider if the specific credit position is overcollateralized
        require(collateralRatio(creditPositionId) < 1000, "Position is not eligible for self-liquidation");

        // Perform self-liquidation (simplified logic)
        // ... (transfer collateral to the lender, etc.)

        delete creditPositions[creditPositionId];
    }

    // Function to create a new credit position
    function createCreditPosition(uint256 collateralAmount, uint256 debtAmount) public {
        creditPositions[creditPositionCounter] = CreditPosition({
            collateralAmount: collateralAmount,
            debtAmount: debtAmount,
            lender: msg.sender
        });
        creditPositionCounter++;
    }
}
```
1. Alice (Lender) creates Credit Position 1:
    - Collateral: 100 ETH
    - Debt: 5000 USDC (Collateral Ratio: 2000, healthy)

2. Bob (Borrower) creates Credit Position 2:
    - Collateral: 10 ETH
    - Debt: 9000 USDC (Collateral Ratio: 111, risky)

3. Bob's Overall Collateralization:
    - Total Collateral: 110 ETH
    - Total Debt: 14000 USDC
    - Overall Collateral Ratio: 785 (below 1000, considered risky)

4. Alice Exploits the Bug:
    - Alice calls `selfLiquidate(1)` for Credit Position 1.
    - Credit Position 1 is overcollateralized, but the contract only checks the overall collateral ratio (785), below 1000.
    - Alice successfully self-liquidates Credit Position 1, receiving 100 ETH for a 5000 USDC debt, making a profit.

