contract RepayTest is BaseTest {
    function test_early_repay_frontrun() public {

        //Setup
        _deposit(alice, weth, 100e18);
        _deposit(alice, usdc, 100e6);
        _deposit(bob, weth, 100e18);
        _deposit(bob, usdc, 100e6);
        _deposit(candy, weth, 100e18);
        _deposit(candy, usdc, 100e6);



        //Alice offers a loan
        _buyCreditLimit(alice, block.timestamp + 365 days, YieldCurveHelper.pointCurve(365 days, 0.05e18));

        //Bob get the loan
        uint256 debtPositionId = _sellCreditMarket(bob, alice, RESERVED_ID, 10e6, 365 days, false);

        //Alice decides to put the newly acquired credit for sale
        _sellCreditLimit(alice, YieldCurveHelper.pointCurve(365 days, 0.05e18));

        uint256 futureValue = size.getDebtPosition(debtPositionId).futureValue;
        uint256 creditPositionId = size.getCreditPositionIdsByDebtPositionId(debtPositionId)[0];


        //Take a snapshot to show difference in revenue for alice with and without a frontrunner 
        uint256 snapshot = vm.snapshot(); 


        ///////////////////////////////////////////////////////////
                         //Without frontrun

