        bytes[] memory data = new bytes[](4);
        data[0] = abi.encodeCall(size.deposit, (DepositParams({token: address(usdc), amount: futureValue, to: liquidator})));
        data[1] = abi.encodeCall(size.liquidate, (LiquidateParams({debtPositionId: debtPositionId, minimumCollateralProfit: 0})));
        data[2] = abi.encodeCall(size.withdraw, (WithdrawParams({token: address(weth), amount: type(uint256).max, to: liquidator})));
        data[3] = abi.encodeCall(size.withdraw, (WithdrawParams({token: address(usdc), amount: type(uint256).max, to: liquidator})));

        // Execute multicall
        vm.prank(liquidator);
        size.multicall(data);

